/* Installments are immutable provider/scheduling evidence, never financial recipes. */
ALTER TABLE finance.card_installment_plan ADD CONSTRAINT fk_installment_current FOREIGN KEY(workspace_id,id,current_revision_id) REFERENCES finance.card_installment_revision(workspace_id,plan_id,id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE finance.card_installment_revision ADD CONSTRAINT fk_installment_previous FOREIGN KEY(workspace_id,plan_id,previous_revision_id) REFERENCES finance.card_installment_revision(workspace_id,plan_id,id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE finance.card_installment_application ADD CONSTRAINT fk_installment_application_reversal FOREIGN KEY(workspace_id,reverses_application_id) REFERENCES finance.card_installment_application(workspace_id,id) DEFERRABLE INITIALLY DEFERRED;
DO $$ DECLARE relation text; BEGIN
 FOREACH relation IN ARRAY ARRAY['card_installment_plan','card_installment_revision','card_installment','card_installment_application'] LOOP
  EXECUTE format('REVOKE ALL ON finance.%I FROM PUBLIC,app_domain,auth_adapter,queue_broker,worker_domain,lifecycle_operator',relation);
  EXECUTE format('GRANT SELECT,INSERT ON finance.%I TO app_domain',relation);
  EXECUTE format('GRANT SELECT,DELETE ON finance.%I TO lifecycle_operator',relation);
  EXECUTE format('ALTER TABLE finance.%I ENABLE ROW LEVEL SECURITY',relation);
  EXECUTE format('ALTER TABLE finance.%I FORCE ROW LEVEL SECURITY',relation);
  EXECUTE format('CREATE POLICY installment_owner ON finance.%I TO app_domain USING(workspace_id=NULLIF(current_setting(''app.workspace_id'',true),'''')::uuid AND EXISTS(SELECT 1 FROM core.workspace w JOIN core.user_profile p ON p.user_id=w.owner_user_id WHERE w.id=workspace_id AND w.owner_user_id=NULLIF(current_setting(''app.user_id'',true),'''')::uuid AND w.state=''active'' AND p.lifecycle=''active'')) WITH CHECK(workspace_id=NULLIF(current_setting(''app.workspace_id'',true),'''')::uuid AND EXISTS(SELECT 1 FROM core.workspace w JOIN core.user_profile p ON p.user_id=w.owner_user_id WHERE w.id=workspace_id AND w.owner_user_id=NULLIF(current_setting(''app.user_id'',true),'''')::uuid AND w.state=''active'' AND p.lifecycle=''active''))',relation);
  EXECUTE format('CREATE POLICY lifecycle_purge_scope ON finance.%I TO lifecycle_operator USING(ops.purge_scope_allowed(workspace_id))',relation);
  EXECUTE format('CREATE TRIGGER a_installment_root BEFORE INSERT OR UPDATE ON finance.%I FOR EACH ROW EXECUTE FUNCTION finance.guard_financial_root_write()',relation);
 END LOOP;
END $$;
GRANT UPDATE ON finance.card_installment_plan,finance.card_installment_revision TO app_domain;
CREATE TRIGGER installment_line_immutable BEFORE UPDATE OR DELETE ON finance.card_installment FOR EACH ROW EXECUTE FUNCTION finance.enforce_debt_append_only_evidence();
CREATE TRIGGER installment_application_immutable BEFORE UPDATE OR DELETE ON finance.card_installment_application FOR EACH ROW EXECUTE FUNCTION finance.enforce_debt_append_only_evidence();
CREATE TRIGGER installment_plan_delete BEFORE DELETE ON finance.card_installment_plan FOR EACH ROW EXECUTE FUNCTION finance.enforce_debt_append_only_evidence();
--> statement-breakpoint
CREATE FUNCTION finance.installment_refund_evidence(scope uuid,purchase uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT COALESCE(jsonb_agg(jsonb_build_object('actionRevisionId',d.action_revision_id,'amountMinor',d.amount_minor::text) ORDER BY d.action_revision_id),'[]'::jsonb) FROM finance.card_action_detail d JOIN finance.financial_action f ON f.workspace_id=d.workspace_id AND f.id=d.action_id AND f.current_revision_id=d.action_revision_id WHERE d.workspace_id=scope AND d.purchase_action_id=purchase
$$;
CREATE FUNCTION finance.card_installment_snapshot(scope uuid,revision uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('purchaseActionId',p.purchase_action_id,'purchaseActionRevisionId',r.purchase_action_revision_id,'principalMinor',r.principal_minor::text,'installmentCount',r.installment_count,'lifecycle',r.lifecycle,'providerReference',r.provider_reference,'verificationSource',r.verification_source,'verifiedDate',r.verified_date::text,'providerConfirmed',true,'notes',r.notes,'refundEvidence',r.refund_evidence,
 'installments',COALESCE((SELECT jsonb_agg(jsonb_build_object('dueDate',i.due_date::text,'principalMinor',i.principal_minor::text,'interestMinor',i.interest_minor::text,'feeMinor',i.fee_minor::text,'totalMinor',i.total_minor::text,'providerReference',i.provider_reference,'notes',i.notes) ORDER BY i.sequence_no) FROM finance.card_installment i WHERE i.workspace_id=r.workspace_id AND i.plan_revision_id=r.id),'[]'::jsonb)) FROM finance.card_installment_revision r JOIN finance.card_installment_plan p ON p.workspace_id=r.workspace_id AND p.id=r.plan_id WHERE r.workspace_id=scope AND r.id=revision
$$;
CREATE FUNCTION finance.card_installment_application_snapshot(scope uuid,application uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('applicationId',x.id,'planId',p.id,'cardId',p.card_id,'planRevisionId',x.plan_revision_id,'installmentNo',x.installment_no,'allocationId',x.allocation_id,'principalMinor',x.principal_minor::text,'interestMinor',x.interest_minor::text,'feeMinor',x.fee_minor::text,'interestActionRevisionId',x.interest_action_revision_id,'feeActionRevisionId',x.fee_action_revision_id,'confirmationKind',x.confirmation_kind,'confirmationSource',x.confirmation_source,'confirmedDate',x.confirmed_date::text,'reversesApplicationId',x.reverses_application_id) FROM finance.card_installment_application x JOIN finance.card_installment_revision r ON r.workspace_id=x.workspace_id AND r.id=x.plan_revision_id JOIN finance.card_installment_plan p ON p.workspace_id=r.workspace_id AND p.id=r.plan_id WHERE x.workspace_id=scope AND x.id=application
$$;
CREATE VIEW finance.card_installment_evidence_v WITH(security_invoker=true) AS
 SELECT p.workspace_id,p.id AS plan_id,p.card_id,p.purchase_action_id,r.id AS plan_revision_id,r.revision_no,r.lifecycle,r.principal_minor,e.amount_minor AS recognized_purchase_minor,
 (r.lifecycle='active' AND r.state='verified' AND f.current_revision_id=r.purchase_action_revision_id AND e.card_id=p.card_id AND e.amount_minor>=r.principal_minor AND r.refund_evidence=finance.installment_refund_evidence(p.workspace_id,p.purchase_action_id)) AS eligible,
 (f.current_revision_id=r.purchase_action_revision_id AND e.card_id=p.card_id AND e.amount_minor>=r.principal_minor) AS purchase_current,
 (r.refund_evidence=finance.installment_refund_evidence(p.workspace_id,p.purchase_action_id)) AS refunds_current
 FROM finance.card_installment_plan p JOIN finance.card_installment_revision r ON r.workspace_id=p.workspace_id AND r.id=p.current_revision_id JOIN finance.card_recognized_evidence_v e ON e.workspace_id=r.workspace_id AND e.action_revision_id=r.purchase_action_revision_id AND e.action_kind='card_purchase' JOIN finance.financial_action f ON f.workspace_id=e.workspace_id AND f.id=e.action_id;
CREATE VIEW finance.effective_card_installment_application_v WITH(security_invoker=true) AS
 SELECT x.* FROM finance.card_installment_application x JOIN finance.card_installment_evidence_v p ON p.workspace_id=x.workspace_id AND p.plan_revision_id=x.plan_revision_id AND p.eligible JOIN finance.effective_card_allocation_v a ON a.workspace_id=x.workspace_id AND a.id=x.allocation_id JOIN finance.card_statement_revision sr ON sr.workspace_id=a.workspace_id AND sr.id=a.statement_revision_id JOIN finance.card_statement s ON s.workspace_id=sr.workspace_id AND s.id=sr.statement_id AND s.card_id=p.card_id JOIN finance.card_recognized_evidence_v payment ON payment.workspace_id=a.workspace_id AND payment.action_revision_id=a.source_action_revision_id
 WHERE x.reverses_application_id IS NULL AND NOT EXISTS(SELECT 1 FROM finance.card_installment_application undo WHERE undo.workspace_id=x.workspace_id AND undo.reverses_application_id=x.id) AND x.confirmed_date>=a.confirmed_date AND x.confirmed_date>=payment.transaction_date
 AND (x.interest_minor=0 OR EXISTS(SELECT 1 FROM finance.card_recognized_evidence_v c JOIN finance.financial_action f ON f.workspace_id=c.workspace_id AND f.id=c.action_id AND f.current_revision_id=c.action_revision_id WHERE c.workspace_id=x.workspace_id AND c.action_revision_id=x.interest_action_revision_id AND c.action_kind='card_interest' AND c.card_id=p.card_id AND c.transaction_date<=x.confirmed_date))
 AND (x.fee_minor=0 OR EXISTS(SELECT 1 FROM finance.card_recognized_evidence_v c JOIN finance.financial_action f ON f.workspace_id=c.workspace_id AND f.id=c.action_id AND f.current_revision_id=c.action_revision_id WHERE c.workspace_id=x.workspace_id AND c.action_revision_id=x.fee_action_revision_id AND c.action_kind='card_fee' AND c.card_id=p.card_id AND c.transaction_date<=x.confirmed_date));
REVOKE ALL ON finance.card_installment_evidence_v,finance.effective_card_installment_application_v FROM PUBLIC;
GRANT SELECT ON finance.card_installment_evidence_v,finance.effective_card_installment_application_v TO app_domain,lifecycle_operator;
--> statement-breakpoint
CREATE FUNCTION finance.guard_card_installment_nonfinancial() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM core.command_receipt c WHERE c.workspace_id=NEW.workspace_id AND c.id=NEW.command_receipt_id AND c.command_type IN('finance.record_card_installment_plan','finance.revise_card_installment_plan','finance.record_card_installment_application','finance.reverse_card_installment_application')) THEN RAISE EXCEPTION 'installment evidence commands cannot create financial revisions' USING ERRCODE='23514'; END IF; RETURN NEW;
END $$;
CREATE TRIGGER action_revision_installment_command BEFORE INSERT ON finance.action_revision FOR EACH ROW EXECUTE FUNCTION finance.guard_card_installment_nonfinancial();
CREATE FUNCTION finance.guard_card_installment_root() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF TG_OP='INSERT' THEN IF NEW.version<>1 OR NEW.current_revision_id IS NOT NULL THEN RAISE EXCEPTION 'installment plan requires initial identity' USING ERRCODE='23514'; END IF; NEW.created_at:=clock_timestamp(); NEW.updated_at:=NEW.created_at;
 ELSE IF NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id OR NEW.card_id<>OLD.card_id OR NEW.purchase_action_id<>OLD.purchase_action_id OR NEW.created_at<>OLD.created_at OR NEW.current_revision_id IS NULL OR NEW.current_revision_id IS NOT DISTINCT FROM OLD.current_revision_id OR NEW.version<>(CASE WHEN OLD.current_revision_id IS NULL THEN 1 ELSE OLD.version+1 END) THEN RAISE EXCEPTION 'installment identity and revision chain are protected' USING ERRCODE='23514'; END IF; NEW.updated_at:=clock_timestamp(); END IF; RETURN NEW;
END $$;
CREATE TRIGGER installment_root_guard BEFORE INSERT OR UPDATE ON finance.card_installment_plan FOR EACH ROW EXECUTE FUNCTION finance.guard_card_installment_root();
CREATE FUNCTION finance.guard_card_installment_revision() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF TG_OP='DELETE' AND current_user='lifecycle_operator' AND ops.purge_scope_allowed(OLD.workspace_id) THEN RETURN OLD; END IF;
 IF TG_OP='INSERT' THEN IF NEW.state<>'building' OR NEW.finalized_at IS NOT NULL OR NEW.recorded_by_user_id IS DISTINCT FROM NULLIF(current_setting('app.user_id',true),'')::uuid THEN RAISE EXCEPTION 'installment requires building owned provider evidence' USING ERRCODE='23514'; END IF; NEW.created_at:=clock_timestamp(); RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND OLD.state='building' AND NEW.state='verified' AND (to_jsonb(NEW)-ARRAY['state','finalized_at'])=(to_jsonb(OLD)-ARRAY['state','finalized_at']) THEN NEW.finalized_at:=clock_timestamp(); RETURN NEW; END IF;
 RAISE EXCEPTION 'installment snapshots are immutable; create a new revision' USING ERRCODE='23514';
END $$;
CREATE TRIGGER installment_revision_guard BEFORE INSERT OR UPDATE OR DELETE ON finance.card_installment_revision FOR EACH ROW EXECUTE FUNCTION finance.guard_card_installment_revision();
CREATE FUNCTION finance.guard_card_installment_line() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM finance.card_installment_revision r WHERE r.workspace_id=NEW.workspace_id AND r.id=NEW.plan_revision_id AND r.state='building') THEN RAISE EXCEPTION 'installment lines require a building snapshot' USING ERRCODE='23514'; END IF; RETURN NEW;
END $$;
CREATE TRIGGER installment_line_guard BEFORE INSERT ON finance.card_installment FOR EACH ROW EXECUTE FUNCTION finance.guard_card_installment_line();
CREATE FUNCTION finance.validate_card_installment_integrity() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE p finance.card_installment_plan%ROWTYPE; r finance.card_installment_revision%ROWTYPE; source finance.card_recognized_evidence_v%ROWTYPE; receipt core.command_receipt%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='card_installment_plan' THEN SELECT * INTO p FROM finance.card_installment_plan WHERE workspace_id=NEW.workspace_id AND id=NEW.id; IF NOT FOUND THEN RETURN NULL; END IF; SELECT * INTO r FROM finance.card_installment_revision WHERE workspace_id=p.workspace_id AND id=p.current_revision_id AND plan_id=p.id; IF NOT FOUND OR r.revision_no<>p.version THEN RAISE EXCEPTION 'plan requires current verified snapshot' USING ERRCODE='23514'; END IF;
 ELSE SELECT * INTO r FROM finance.card_installment_revision WHERE workspace_id=NEW.workspace_id AND id=NEW.id; IF NOT FOUND THEN RETURN NULL; END IF; SELECT * INTO p FROM finance.card_installment_plan WHERE workspace_id=r.workspace_id AND id=r.plan_id; END IF;
 IF r.state<>'verified' OR p.current_revision_id IS NULL OR p.version<r.revision_no OR (r.revision_no>1 AND NOT EXISTS(SELECT 1 FROM finance.card_installment_revision prev WHERE prev.workspace_id=r.workspace_id AND prev.plan_id=p.id AND prev.id=r.previous_revision_id AND prev.revision_no=r.revision_no-1 AND prev.state='verified')) OR (r.revision_no=1 AND r.lifecycle<>'active') THEN RAISE EXCEPTION 'plan requires sequential finalized provider revisions' USING ERRCODE='23514'; END IF;
 SELECT * INTO source FROM finance.card_recognized_evidence_v WHERE workspace_id=r.workspace_id AND action_revision_id=r.purchase_action_revision_id AND action_kind='card_purchase' AND action_id=p.purchase_action_id AND card_id=p.card_id;
 IF NOT FOUND OR r.principal_minor>source.amount_minor OR (r.lifecycle='active' AND (NOT EXISTS(SELECT 1 FROM finance.financial_action f WHERE f.workspace_id=r.workspace_id AND f.id=p.purchase_action_id AND f.current_revision_id=r.purchase_action_revision_id) OR r.refund_evidence<>finance.installment_refund_evidence(r.workspace_id,p.purchase_action_id))) OR (r.lifecycle='cancelled' AND NOT EXISTS(SELECT 1 FROM finance.card_installment_revision prev WHERE prev.workspace_id=r.workspace_id AND prev.id=r.previous_revision_id AND prev.purchase_action_revision_id=r.purchase_action_revision_id AND prev.refund_evidence=r.refund_evidence)) THEN RAISE EXCEPTION 'plan requires supported same-card purchase and explicit current refund evidence, or retained cancellation evidence' USING ERRCODE='23514'; END IF;
 IF (SELECT count(*) FROM finance.card_installment WHERE workspace_id=r.workspace_id AND plan_revision_id=r.id)<>r.installment_count OR (SELECT COALESCE(max(sequence_no),0) FROM finance.card_installment WHERE workspace_id=r.workspace_id AND plan_revision_id=r.id)<>r.installment_count OR (SELECT COALESCE(sum(principal_minor::numeric),0) FROM finance.card_installment WHERE workspace_id=r.workspace_id AND plan_revision_id=r.id)<>r.principal_minor::numeric OR EXISTS(SELECT 1 FROM finance.card_installment i WHERE i.workspace_id=r.workspace_id AND i.plan_revision_id=r.id AND (i.due_date<source.transaction_date OR EXISTS(SELECT 1 FROM finance.card_installment prior WHERE prior.workspace_id=i.workspace_id AND prior.plan_revision_id=i.plan_revision_id AND prior.sequence_no<i.sequence_no AND prior.due_date>i.due_date))) THEN RAISE EXCEPTION 'complete provider schedule must match count, principal and known date order' USING ERRCODE='23514'; END IF;
 SELECT * INTO receipt FROM core.command_receipt WHERE workspace_id=r.workspace_id AND id=r.command_receipt_id;
 IF receipt.state IS DISTINCT FROM 'completed' OR receipt.retain_until IS NOT NULL OR receipt.command_type IS DISTINCT FROM (CASE WHEN r.revision_no=1 THEN 'finance.record_card_installment_plan' ELSE 'finance.revise_card_installment_plan' END) OR NOT receipt.result_json @> jsonb_build_object('planId',p.id,'revisionId',r.id,'version',r.revision_no) OR EXISTS(SELECT 1 FROM finance.action_revision a WHERE a.workspace_id=r.workspace_id AND a.command_receipt_id=r.command_receipt_id) THEN RAISE EXCEPTION 'plan requires completed evidence-only receipt' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM audit.private_revision a WHERE a.workspace_id=r.workspace_id AND a.command_receipt_id=r.command_receipt_id AND a.subject_kind='card_installment_plan' AND a.subject_id=p.id AND a.subject_version=r.revision_no AND a.operation=CASE WHEN r.revision_no=1 THEN 'create' ELSE 'replace' END AND a.recorded_by_user_id=r.recorded_by_user_id AND a.actor_kind='user' AND a.request_id IS NOT DISTINCT FROM r.request_id AND a.reason IS NOT DISTINCT FROM r.reason AND a.effective_date=r.verified_date AND a.after_json=finance.card_installment_snapshot(r.workspace_id,r.id) AND a.before_json IS NOT DISTINCT FROM CASE WHEN r.previous_revision_id IS NULL THEN NULL ELSE finance.card_installment_snapshot(r.workspace_id,r.previous_revision_id) END) THEN RAISE EXCEPTION 'plan requires exact immutable attributed before/after audit evidence' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT plans.purchase_action_id FROM finance.card_installment_plan plans JOIN finance.card_installment_revision current_snapshot ON current_snapshot.workspace_id=plans.workspace_id AND current_snapshot.id=plans.current_revision_id AND current_snapshot.lifecycle='active' WHERE plans.workspace_id=p.workspace_id GROUP BY plans.purchase_action_id HAVING count(*)>1) THEN RAISE EXCEPTION 'revise or cancel the existing active purchase plan' USING ERRCODE='23514'; END IF; RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER installment_root_integrity AFTER INSERT OR UPDATE ON finance.card_installment_plan DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION finance.validate_card_installment_integrity();
CREATE CONSTRAINT TRIGGER installment_revision_integrity AFTER INSERT OR UPDATE ON finance.card_installment_revision DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION finance.validate_card_installment_integrity();
--> statement-breakpoint
CREATE FUNCTION finance.guard_card_installment_application() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE original finance.card_installment_application%ROWTYPE;
BEGIN
 IF NEW.recorded_by_user_id IS DISTINCT FROM NULLIF(current_setting('app.user_id',true),'')::uuid THEN RAISE EXCEPTION 'application requires trusted owner attribution' USING ERRCODE='23514'; END IF; NEW.created_at:=clock_timestamp();
 IF NEW.reverses_application_id IS NOT NULL THEN
  SELECT * INTO original FROM finance.card_installment_application WHERE workspace_id=NEW.workspace_id AND id=NEW.reverses_application_id;
  IF NOT FOUND OR original.reverses_application_id IS NOT NULL OR (to_jsonb(NEW)-ARRAY['id','command_receipt_id','confirmation_source','reverses_application_id','recorded_by_user_id','request_id','created_at'])<>(to_jsonb(original)-ARRAY['id','command_receipt_id','confirmation_source','reverses_application_id','recorded_by_user_id','request_id','created_at']) THEN RAISE EXCEPTION 'application reversal must exactly reverse one original confirmation' USING ERRCODE='23514'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM finance.card_installment_evidence_v p JOIN finance.effective_card_allocation_v a ON a.workspace_id=p.workspace_id AND a.id=NEW.allocation_id JOIN finance.card_statement_revision sr ON sr.workspace_id=a.workspace_id AND sr.id=a.statement_revision_id JOIN finance.card_statement s ON s.workspace_id=sr.workspace_id AND s.id=sr.statement_id AND s.card_id=p.card_id JOIN finance.card_recognized_evidence_v payment ON payment.workspace_id=a.workspace_id AND payment.action_revision_id=a.source_action_revision_id WHERE p.workspace_id=NEW.workspace_id AND p.plan_revision_id=NEW.plan_revision_id AND p.eligible AND NEW.confirmed_date>=a.confirmed_date AND NEW.confirmed_date>=payment.transaction_date) THEN RAISE EXCEPTION 'application requires current eligible plan and confirmed same-card A4 allocation' USING ERRCODE='23514'; END IF;
  IF NEW.interest_minor>0 AND NOT EXISTS(SELECT 1 FROM finance.card_installment_evidence_v p JOIN finance.card_recognized_evidence_v c ON c.workspace_id=p.workspace_id AND c.card_id=p.card_id JOIN finance.financial_action f ON f.workspace_id=c.workspace_id AND f.id=c.action_id AND f.current_revision_id=c.action_revision_id WHERE p.workspace_id=NEW.workspace_id AND p.plan_revision_id=NEW.plan_revision_id AND c.action_revision_id=NEW.interest_action_revision_id AND c.action_kind='card_interest' AND c.transaction_date<=NEW.confirmed_date) THEN RAISE EXCEPTION 'applied interest requires actual current recognized charge' USING ERRCODE='23514'; END IF;
  IF NEW.fee_minor>0 AND NOT EXISTS(SELECT 1 FROM finance.card_installment_evidence_v p JOIN finance.card_recognized_evidence_v c ON c.workspace_id=p.workspace_id AND c.card_id=p.card_id JOIN finance.financial_action f ON f.workspace_id=c.workspace_id AND f.id=c.action_id AND f.current_revision_id=c.action_revision_id WHERE p.workspace_id=NEW.workspace_id AND p.plan_revision_id=NEW.plan_revision_id AND c.action_revision_id=NEW.fee_action_revision_id AND c.action_kind='card_fee' AND c.transaction_date<=NEW.confirmed_date) THEN RAISE EXCEPTION 'applied fee requires actual current recognized charge' USING ERRCODE='23514'; END IF;
 END IF; RETURN NEW;
END $$;
CREATE TRIGGER installment_application_guard BEFORE INSERT ON finance.card_installment_application FOR EACH ROW EXECUTE FUNCTION finance.guard_card_installment_application();
CREATE FUNCTION finance.validate_card_installment_application() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE x finance.card_installment_application%ROWTYPE;
BEGIN
 SELECT * INTO x FROM finance.card_installment_application WHERE workspace_id=NEW.workspace_id AND id=NEW.id; IF NOT FOUND THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM core.command_receipt c WHERE c.workspace_id=x.workspace_id AND c.id=x.command_receipt_id AND c.state='completed' AND c.retain_until IS NULL AND c.command_type=CASE WHEN x.reverses_application_id IS NULL THEN 'finance.record_card_installment_application' ELSE 'finance.reverse_card_installment_application' END AND c.result_json @> jsonb_build_object('applicationId',x.id)) OR EXISTS(SELECT 1 FROM finance.action_revision WHERE workspace_id=x.workspace_id AND command_receipt_id=x.command_receipt_id) THEN RAISE EXCEPTION 'application requires completed nonfinancial receipt' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM audit.private_revision a WHERE a.workspace_id=x.workspace_id AND a.command_receipt_id=x.command_receipt_id AND a.subject_kind='card_installment_application' AND a.subject_id=x.id AND a.subject_version=1 AND a.recorded_by_user_id=x.recorded_by_user_id AND a.actor_kind='user' AND a.request_id IS NOT DISTINCT FROM x.request_id AND a.effective_date=x.confirmed_date AND a.after_json=finance.card_installment_application_snapshot(x.workspace_id,x.id) AND a.operation=CASE WHEN x.reverses_application_id IS NULL THEN 'create' ELSE 'void' END AND (CASE WHEN x.reverses_application_id IS NULL THEN a.before_json IS NULL AND a.reason IS NULL ELSE a.before_json=finance.card_installment_application_snapshot(x.workspace_id,x.reverses_application_id) AND a.reason=x.confirmation_source END)) THEN RAISE EXCEPTION 'application requires exact original/confirmation audit evidence' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM finance.effective_card_installment_application_v e JOIN finance.effective_card_allocation_v a ON a.workspace_id=e.workspace_id AND a.id=e.allocation_id WHERE e.workspace_id=x.workspace_id GROUP BY a.id,a.amount_minor HAVING sum(e.principal_minor::numeric+e.interest_minor::numeric+e.fee_minor::numeric)>a.amount_minor::numeric)
 OR EXISTS(SELECT 1 FROM finance.effective_card_installment_application_v e JOIN finance.card_installment i ON i.workspace_id=e.workspace_id AND i.plan_revision_id=e.plan_revision_id AND i.sequence_no=e.installment_no WHERE e.workspace_id=x.workspace_id GROUP BY i.id,i.principal_minor,i.interest_minor,i.fee_minor,i.total_minor HAVING sum(e.principal_minor::numeric)>i.principal_minor::numeric OR (sum(e.interest_minor::numeric)>0 AND (i.interest_minor IS NULL OR sum(e.interest_minor::numeric)>i.interest_minor::numeric)) OR (sum(e.fee_minor::numeric)>0 AND (i.fee_minor IS NULL OR sum(e.fee_minor::numeric)>i.fee_minor::numeric)) OR (i.total_minor IS NOT NULL AND sum(e.principal_minor::numeric+e.interest_minor::numeric+e.fee_minor::numeric)>i.total_minor::numeric))
 OR EXISTS(SELECT 1 FROM finance.effective_card_installment_application_v e JOIN finance.card_recognized_evidence_v c ON c.workspace_id=e.workspace_id AND c.action_revision_id=e.interest_action_revision_id WHERE e.workspace_id=x.workspace_id GROUP BY c.action_revision_id,c.amount_minor HAVING sum(e.interest_minor::numeric)>c.amount_minor::numeric)
 OR EXISTS(SELECT 1 FROM finance.effective_card_installment_application_v e JOIN finance.card_recognized_evidence_v c ON c.workspace_id=e.workspace_id AND c.action_revision_id=e.fee_action_revision_id WHERE e.workspace_id=x.workspace_id GROUP BY c.action_revision_id,c.amount_minor HAVING sum(e.fee_minor::numeric)>c.amount_minor::numeric) THEN RAISE EXCEPTION 'applications exceed supported allocation, installment or actual charge evidence' USING ERRCODE='23514'; END IF; RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER installment_application_integrity AFTER INSERT ON finance.card_installment_application DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION finance.validate_card_installment_application();
DO $$ DECLARE fn text; BEGIN
 FOREACH fn IN ARRAY ARRAY['guard_card_installment_nonfinancial','guard_card_installment_root','guard_card_installment_revision','guard_card_installment_line','validate_card_installment_integrity','guard_card_installment_application','validate_card_installment_application'] LOOP EXECUTE format('REVOKE ALL ON FUNCTION finance.%I() FROM PUBLIC',fn); EXECUTE format('GRANT EXECUTE ON FUNCTION finance.%I() TO app_domain,lifecycle_operator',fn); END LOOP;
END $$;
REVOKE ALL ON FUNCTION finance.installment_refund_evidence(uuid,uuid),finance.card_installment_snapshot(uuid,uuid),finance.card_installment_application_snapshot(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION finance.installment_refund_evidence(uuid,uuid),finance.card_installment_snapshot(uuid,uuid),finance.card_installment_application_snapshot(uuid,uuid) TO app_domain,lifecycle_operator;
